const controls={rightPressed:!1,leftPressed:!1,isPaused:!1};let listenersAttached=!1;function keyDownHandler(e){(e.code=="KeyD"||e.code=="ArrowRight")&&(controls.rightPressed=!0),(e.code=="KeyA"||e.code=="ArrowLeft")&&(controls.leftPressed=!0),e.code=="KeyP"&&togglePause()}function keyUpHandler(e){(e.code=="KeyD"||e.code=="ArrowRight")&&(controls.rightPressed=!1),(e.code=="KeyA"||e.code=="ArrowLeft")&&(controls.leftPressed=!1)}function mouseMoveHandler(e){if(!controls.isPaused){let relativeX=e.clientX-config.canvas.offsetLeft;relativeX>0+config.paddleWidth/2&&relativeX<config.canvas.width-config.paddleWidth/2&&(gameState.paddleX=relativeX-config.paddleWidth/2)}}function updatePauseButtonText(){elements.pauseBtn&&(elements.pauseBtn.textContent=controls.isPaused?"Resume":"Pause")}function togglePause(){controls.isPaused=!controls.isPaused,updatePauseButtonText()}function reloadPage(){init()}function setupEventListeners(){listenersAttached||(document.addEventListener("keydown",keyDownHandler),document.addEventListener("keyup",keyUpHandler),document.addEventListener("mousemove",mouseMoveHandler),elements.failureBtn.addEventListener("click",reloadPage),elements.successBtn.addEventListener("click",reloadPage),elements.pauseBtn.addEventListener("click",togglePause),listenersAttached=!0)}
